NEW_FILES = {'packages/exporting/buildings_index.py': '"""The buildings a level stands, and their drawings: `buildings.json` at a package\'s root (the factory\'s roadmap 296).\n\nThe walker, of Deli Counter\'s exploded axonometric: seen in "both" a review page and a level\'s export -- "It could\neven get into the game where the players can \'scope out\' the level and see the buildings the level assembles". Since\nDeli Counter 0.257.0 each composed building carries its drawings in its package\'s `drawings/`, with `drawings.json`\nnaming them; which buildings a level stands, and where, was written only into its assembly scene, `site.tscn`, as\ninstances. This reads that scene and those records and writes one index a game or a reviewer reads without parsing a\nscene: each standing instance -- a building `b<n>` or an Empty `blocker_<n>` -- with its package id, the spec it was\ndrawn from, its drawings as `res://` paths (or why it has none), and where it stands: the instance\'s origin in\n`site.tscn`, Godot metres, Y up. The game builds the screen; this is what it reads.\n\nTHE PATHS ARE res:// ON PURPOSE. The export\'s closure scan resolves every `res://` a package\'s JSON names\n(`closure.scan_closure`), so an index naming a drawing the package does not carry fails the package\'s own verdict.\n"""\nfrom __future__ import annotations\n\nimport json\nimport re\nfrom pathlib import Path\n\nINDEX_NAME = "buildings.json"\n_EXT = re.compile(r\'^\\[ext_resource type="PackedScene" path="(lot/([^"/]+)/site\\.tscn)" id="([^"]+)"\\]\', re.M)\n_NODE = re.compile(r\'^\\[node name="([^"]+)" parent="\\." instance=ExtResource\\("([^"]+)"\\)\\]\', re.M)\n_XFORM = re.compile(r\'^transform = Transform3D\\(([^)]*)\\)\', re.M)\nNO_DRAWINGS = "its package carries no drawings (composed by a Deli Counter before 0.257.0, or named no spec)"\n\n\ndef build(package_dir) -> dict | None:\n    """The index for one package, or None where it has no assembly scene (`site.tscn`) to read."""\n    root = Path(package_dir)\n    scene = root / "site.tscn"\n    if not scene.is_file():\n        return None\n    text = scene.read_text(encoding="utf-8", errors="replace")\n    ext = {m.group(3): m.group(2) for m in _EXT.finditer(text)}\n    out = []\n    for m in _NODE.finditer(text):\n        name, rid = m.group(1), m.group(2)\n        if rid not in ext:\n            continue\n        lot_id = ext[rid]\n        # a node\'s properties run to the next section\'s header\n        nxt = text.find("\\n[", m.end())\n        body = text[m.end():nxt if nxt != -1 else len(text)]\n        x = _XFORM.search(body)\n        nums = [float(v) for v in x.group(1).split(",")] if x else []\n        entry = {"node": name, "id": lot_id, "kind": "empty" if name.startswith("blocker_") else "building",\n                 # the Transform3D\'s last three numbers are its origin, however its basis is written\n                 "at": [round(v, 3) for v in nums[9:12]] if len(nums) == 12 else None,\n                 "spec": None, "axonometric": None, "plans": []}\n        rec_path = root / "lot" / lot_id / "drawings" / "drawings.json"\n        if rec_path.is_file():\n            rec = json.loads(rec_path.read_text(encoding="utf-8"))\n            base = "res://lot/%s/drawings/" % lot_id\n            entry["spec"] = rec.get("spec")\n            if rec.get("axonometric"):\n                entry["axonometric"] = base + rec["axonometric"]\n            entry["plans"] = [{"storey": p["storey"], "file": base + p["file"]} for p in rec.get("plans") or []]\n            if rec.get("none_because"):\n                entry["none_because"] = rec["none_because"]\n        else:\n            entry["none_because"] = NO_DRAWINGS\n        out.append(entry)\n    return {"schema": "level_factory.buildings.v1", "scene": "res://site.tscn",\n            "frame": "at: the instance\'s origin in site.tscn, Godot metres, Y up", "buildings": out}\n\n\ndef write(package_dir) -> dict | None:\n    """Write `buildings.json` into the package; returns the index, or None (and writes nothing) where `build` has\n    no scene to read."""\n    index = build(package_dir)\n    if index is None:\n        return None\n    (Path(package_dir) / INDEX_NAME).write_text(json.dumps(index, indent=2) + "\\n", encoding="utf-8", newline="\\n")\n    return index\n\n\ndef summary(index: dict) -> str:\n    """One line for the export\'s log: how many instances, how many drawn, how many say why not."""\n    b = index["buildings"]\n    drawn = sum(1 for e in b if e["axonometric"])\n    return "%d instance(s) of %d package(s); %d drawn, %d with a reason for none" % (\n        len(b), len({e["id"] for e in b}), drawn, sum(1 for e in b if e.get("none_because")))\n', 'tests/unit/test_buildings_index.py': '"""A level\'s package names the buildings it stands, where, and their drawings (0.232.0, the factory\'s roadmap 296).\n\n`buildings_index` reads the shipped assembly scene and each building package\'s own `drawings/drawings.json` (Deli\nCounter 0.257.0) and writes `buildings.json` at the package\'s root. A synthetic package: two buildings and an Empty in\n`site.tscn`, the scene\'s shape read off cold run 9376\'s package (`[ext_resource ... path="lot/<id>/site.tscn"]`,\n`[node name="b0" parent="." instance=ExtResource("b1")]`, `transform = Transform3D(...)`).\n"""\nfrom __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nfrom packages.exporting import buildings_index as BI\nfrom packages.exporting.closure import scan_closure\n\nSCENE = """[gd_scene load_steps=4 format=3]\n\n[ext_resource type="PackedScene" path="lot/deli_a03/site.tscn" id="b1"]\n[ext_resource type="PackedScene" path="lot/office/site.tscn" id="b2"]\n[ext_resource type="PackedScene" path="lot/gs_empty_rowhome_a/site.tscn" id="b3"]\n\n[node name="site" type="Node3D"]\n\n[node name="b0" parent="." instance=ExtResource("b1")]\ntransform = Transform3D(1, 0, 0, 0, 1, 0, -0, 0, 1, -51, 0, -2.51)\n\n[node name="b1" parent="." instance=ExtResource("b2")]\ntransform = Transform3D(1, 0, 0, 0, 1, 0, 0, 0, 1, 12.5, 0, 4)\n\n[node name="blocker_0" parent="." instance=ExtResource("b3")]\ntransform = Transform3D(-1, 0, 1.22465e-16, 0, 1, 0, -1.22465e-16, 0, -1, -83.2, 0, 37.815)\n"""\n\n\ndef _package(tmp_path: Path, *, office_drawn=True) -> Path:\n    root = tmp_path / "pkg"\n    root.mkdir()\n    (root / "site.tscn").write_text(SCENE, encoding="utf-8")\n    for lot_id in ("deli_a03", "office", "gs_empty_rowhome_a"):\n        (root / "lot" / lot_id).mkdir(parents=True)\n        (root / "lot" / lot_id / "site.tscn").write_text(\'[gd_scene format=3]\\n\\n[node name="site" type="Node3D"]\\n\',\n                                                          encoding="utf-8")\n    d = root / "lot" / "deli_a03" / "drawings"\n    d.mkdir()\n    for f in ("axonometric.svg", "floorB1.svg", "floor0.svg"):\n        (d / f).write_text("<svg/>", encoding="utf-8")\n    (d / "drawings.json").write_text(json.dumps({\n        "schema": "deli_counter.drawings.v1", "spec": "deli_a03", "axonometric": "axonometric.svg",\n        "plans": [{"storey": -1, "file": "floorB1.svg"}, {"storey": 0, "file": "floor0.svg"}]}), encoding="utf-8")\n    if office_drawn:\n        d = root / "lot" / "office" / "drawings"\n        d.mkdir()\n        (d / "axonometric.svg").write_text("<svg/>", encoding="utf-8")\n        (d / "drawings.json").write_text(json.dumps({\n            "schema": "deli_counter.drawings.v1", "spec": "office", "axonometric": "axonometric.svg",\n            "plans": []}), encoding="utf-8")\n    d = root / "lot" / "gs_empty_rowhome_a" / "drawings"\n    d.mkdir()\n    (d / "drawings.json").write_text(json.dumps({\n        "schema": "deli_counter.drawings.v1", "spec": "gs_empty_rowhome_a", "axonometric": None, "plans": [],\n        "none_because": "a facade: a street wall with no interior"}), encoding="utf-8")\n    return root\n\n\ndef test_every_standing_instance_is_named_with_where_it_stands_and_its_drawings(tmp_path):\n    root = _package(tmp_path)\n    index = BI.write(root)\n    assert json.loads((root / BI.INDEX_NAME).read_text(encoding="utf-8")) == index\n    by_node = {e["node"]: e for e in index["buildings"]}\n    assert list(by_node) == ["b0", "b1", "blocker_0"]\n    deli = by_node["b0"]\n    assert (deli["id"], deli["kind"], deli["spec"], deli["at"]) == ("deli_a03", "building", "deli_a03",\n                                                                    [-51.0, 0.0, -2.51])\n    assert deli["axonometric"] == "res://lot/deli_a03/drawings/axonometric.svg"\n    assert deli["plans"] == [{"storey": -1, "file": "res://lot/deli_a03/drawings/floorB1.svg"},\n                             {"storey": 0, "file": "res://lot/deli_a03/drawings/floor0.svg"}]\n    empty = by_node["blocker_0"]\n    assert (empty["kind"], empty["at"], empty["axonometric"]) == ("empty", [-83.2, 0.0, 37.815], None)\n    assert "facade" in empty["none_because"]\n\n\ndef test_a_package_without_drawings_says_so(tmp_path):\n    root = _package(tmp_path, office_drawn=False)\n    office = {e["node"]: e for e in BI.write(root)["buildings"]}["b1"]\n    assert office["axonometric"] is None and office["none_because"] == BI.NO_DRAWINGS\n\n\ndef test_a_package_with_no_assembly_scene_gets_no_index(tmp_path):\n    root = tmp_path / "pkg"\n    root.mkdir()\n    assert BI.write(root) is None and not (root / BI.INDEX_NAME).exists()\n\n\ndef test_the_closure_verdict_proves_every_drawing_the_index_names(tmp_path):\n    """The index names its drawings res://, which the closure scan resolves: with every drawing present it raises\n    nothing about the index; take one away and the verdict names the index\'s reference to it."""\n    root = _package(tmp_path)\n    BI.write(root)\n    assert not [i for i in scan_closure(root).issues if i.startswith(BI.INDEX_NAME)]\n    (root / "lot" / "deli_a03" / "drawings" / "floor0.svg").unlink()\n    issues = [i for i in scan_closure(root).issues if i.startswith(BI.INDEX_NAME)]\n    assert issues == ["%s: unresolved res://lot/deli_a03/drawings/floor0.svg" % BI.INDEX_NAME], issues\n', 'tests/unit/test_compose_draws_its_buildings.py': '"""Each building\'s compose names the spec it was built from, so its package carries its drawings (0.232.0, the\nfactory\'s roadmap 296).\n\nDeli Counter 0.257.0\'s `build_package` draws a building into its package\'s `drawings/` when it is named the spec. The\nlibrary row reports the spec beside the build dir (`building_library.index`\'s `spec`, never used to exclude), the\npresentation adapter hands it to the driver (`--spec`), and the driver passes it on only where it can be answered\n(`_drawing_kwargs`). Pure, on `test_fanout`\'s stand-in library and the real planner, spec builder and adapter.\n"""\nfrom __future__ import annotations\n\nimport importlib.util\nimport json\nimport sys\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\nsys.path.insert(0, str(Path(__file__).resolve().parent))\n\nfrom packages.pipeline import building_library as bl\nfrom test_fanout import ARCHETYPES, _brief, _compose_args, _flag, _library, _plan, _specs, _stages\n\nROOT = Path(__file__).resolve().parents[2]\n\n\ndef _with_specs(build: Path, ids) -> None:\n    specs = build.parent / "specs"\n    specs.mkdir(exist_ok=True)\n    for aid in ids:\n        (specs / (aid + ".json")).write_text(json.dumps({"name": aid}), encoding="utf-8")\n\n\ndef test_a_library_row_names_its_spec_where_deli_counter_has_one(tmp_path):\n    build = _library(tmp_path / "build")\n    _with_specs(build, ARCHETYPES[:3])\n    rows = {r["id"]: r for r in bl.index(build)[0]}\n    for aid in ARCHETYPES[:3]:\n        assert rows[aid]["spec"] == str(tmp_path / "specs" / (aid + ".json"))\n    for aid in ARCHETYPES[3:]:\n        assert rows[aid]["spec"] == ""\n\n\ndef test_the_lot_is_drawn_from_the_same_draw_with_or_without_specs(tmp_path, monkeypatch):\n    """The spec is reported, never used to exclude: the lot a seed picks is the same lot."""\n    a = _specs(tmp_path / "a", _plan(_brief(_library(tmp_path / "a" / "build"))),\n               _brief(_library(tmp_path / "a" / "build")), monkeypatch)\n    build_b = _library(tmp_path / "b" / "build")\n    _with_specs(build_b, ARCHETYPES)\n    b = _specs(tmp_path / "b", _plan(_brief(build_b)), _brief(build_b), monkeypatch)\n    ids = lambda specs: [[r["id"] for r in s.get("lot_archetypes") or []] for s in specs.values()]  # noqa: E731\n    assert ids(a) == ids(b) and any(ids(a))\n\n\ndef test_each_building_s_compose_names_its_own_spec(tmp_path, monkeypatch):\n    build = _library(tmp_path / "build")\n    _with_specs(build, ARCHETYPES)\n    brief = _brief(build)\n    plan = _plan(brief)\n    specs = _specs(tmp_path, plan, brief, monkeypatch)\n    compose = _stages(plan, "presentation_compose")[0]\n    spec = specs[compose.job_id]\n    args = _compose_args(spec, tmp_path)\n    by_slots = {_flag(a, "--slots"): _flag(a, "--spec") for a in args}\n    for row in spec["lot_archetypes"]:\n        assert by_slots[row["slots"]] == str(tmp_path / "specs" / (row["id"] + ".json"))\n    # the mission\'s own shell: the spec the Deli Counter job writes, lf_<mission>_<seed>\n    seed = int(compose.candidate_id.rsplit("_", 1)[-1])\n    assert spec["shell_spec"] == str(tmp_path / "repos" / "deli_counter" / "specs" /\n                                     ("lf_%s_%d.json" % (brief.mission_id, seed)))\n    assert _flag(args[0], "--spec") == spec["shell_spec"]\n\n\ndef _driver():\n    path = ROOT / "assets" / "scripts" / "run_presentation_compose.py"\n    s = importlib.util.spec_from_file_location("run_presentation_compose_under_test", path)\n    m = importlib.util.module_from_spec(s)\n    s.loader.exec_module(m)\n    return m\n\n\ndef test_the_driver_asks_for_drawings_only_where_they_can_be_answered(tmp_path):\n    """A spec that is a file, and a composer that takes one: passed. A composer before Deli Counter 0.257.0, or a\n    spec that is not there, or none: nothing passed, and the reason given -- a drawing is never worth a compose."""\n    d = _driver()\n    spec = tmp_path / "x.json"\n    spec.write_text("{}", encoding="utf-8")\n\n    def new(slots, gameplay, modules, out, *, theme, spec_path=None):\n        return {}\n\n    def old(slots, gameplay, modules, out, *, theme):\n        return {}\n\n    assert d._drawing_kwargs(new, str(spec)) == ({"spec_path": str(spec)}, "")\n    kw, why = d._drawing_kwargs(old, str(spec))\n    assert kw == {} and "0.257.0" in why\n    kw, why = d._drawing_kwargs(new, str(tmp_path / "missing.json"))\n    assert kw == {} and "no spec" in why\n    assert d._drawing_kwargs(new, "") == ({}, "")\n'}
CHANGELOG = '## [0.232.0] - a level\'s package names the buildings it stands, and carries their drawings\n\n**The factory\'s roadmap 296.** The walker, of Deli Counter\'s exploded axonometric (roadmap 293), asked where it is\nseen: "both" -- a review page and a level\'s export -- "It could even get into the game where the players can \'scope\nout\' the level and see the buildings the level assembles". Deli Counter 0.257.0 draws a building into its package\'s\n`drawings/` when the compose names the spec it was built from; nothing here named it, and which buildings a level\nstands, and where, was written only into its assembly scene, as instances.\n\n### Added\n- **`building_library.index` reports each row\'s `spec`**: `specs/<id>.json` beside the build dir, where Deli Counter\n  has one -- it names a build by its spec\'s file stem. Reported, never used to exclude, like `lights` and `navgate`:\n  the lot a seed draws is the lot it drew.\n- **The compose names it.** The presentation adapter passes `--spec` for each building of the lot, and for the\n  mission\'s own shell the spec the Deli Counter job writes (`shell_spec`, `lf_<mission>_<seed>`). The driver passes it\n  on to `build_package` only where it can be answered -- a spec that is a file, and a composer that takes one\n  (`_drawing_kwargs`) -- and says why when not: a drawing is never worth a compose.\n- **`buildings.json` at a package\'s root** (`packages/exporting/buildings_index.py`): every instance the assembly\n  scene stands -- a building `b<n>` or an Empty `blocker_<n>` -- with its package id, the spec it was drawn from, its\n  axonometric and plans as `res://` paths or why it has none, and where it stands (the instance\'s origin in\n  `site.tscn`, Godot metres, Y up). Written after every step that writes a scene and before the closure verdict, which\n  resolves every `res://` a package\'s JSON names: an index naming a drawing the package does not carry fails the\n  package\'s own verdict. The game builds the screen; this is what it reads.\n\n### Tests\n- **test_buildings_index.py**, new, four: every standing instance named, with where it stands and its drawings; a\n  package with none says so; a package with no assembly scene gets no index; the closure verdict proves every drawing\n  the index names (one taken away, the verdict names the index\'s reference to it). On 0.231.0 the file cannot be\n  collected: the module is new.\n- **test_compose_draws_its_buildings.py**, new, four: a library row names its spec where Deli Counter has one; the lot\n  is the same lot with or without specs; each building\'s compose names its own spec and the shell its own; the driver\n  asks for drawings only where they can be answered. On 0.231.0 three fail -- a row has no `spec`, a compose names\n  none, the driver has no `_drawing_kwargs` -- and the same-lot test passes, as it must on both (the factory\'s\n  `patches/lf_drawings/prove_tests_on_0231.out.txt`).\n- **And three cases more, unwritten**: `test_sibling_locator`\'s rule that nothing reaches above this repo by counting\n  parents, parametrized over every source file, asked of the three new files. In clones against a fresh 0.231.0, each\n  with the factory\'s Laser Tag, Lot and Deli Counter named: the same 15 failures on both sides, each needing the\n  factory tree beside the clone, and no other; 2,564 passed against 2,553, the eleven named (the factory\'s\n  `patches/lf_drawings/suite_clone_vs_base.out.txt`, `passed_diff.out.txt`).\n\n### Left\n- (the factory\'s roadmap 296) a walker-review page built from a cold run\'s package; the in-game screen, which is the\n  game\'s.\n\n'
OLD_VERSION, NEW_VERSION = '0.231.0', '0.232.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
